def move_off_romanian(apps, schema_editor):
    """Romanian is no longer served: people and posts that used it move to English.

    Romanian texts stored in {locale: text} maps and ArticleTranslation rows are
    left in place (never served); deleting editorial content is not undoable.
    """
    apps.get_model('third_side', 'ThirdSideUser').objects.filter(language='ro').update(
        language='en'
    )
    apps.get_model('third_side', 'FestivalPost').objects.filter(
        original_language='ro'
    ).update(original_language='en')
    Article = apps.get_model('third_side', 'Article')
    Translation = apps.get_model('third_side', 'ArticleTranslation')
    for article in Article.objects.filter(original_language='ro'):
        has_en = Translation.objects.filter(article=article, locale='en').exists()
        article.original_language = 'en' if has_en else 'ar'
        article.save(update_fields=['original_language'])


